style.css:
@-moz-document domain("youtube.com") {
/* Fundo geral */
  html, body, ytd-app {
    background-color: #0d1117 !important;
  }

  /* Barra superior (masthead) */
  ytd-masthead {
    background-color: #12141f !important;
    border-bottom: 1px solid #6a2c91 !important;
  }

  /* Logo e ícones da barra superior */
  ytd-masthead #logo, ytd-masthead yt-icon {
    filter: hue-rotate(220deg) saturate(1.4);
  }

  /* Sidebar (menu lateral) */
  ytd-guide-renderer, tp-yt-app-drawer {
    background-color: #10121c !important;
  }

  ytd-guide-entry-renderer:hover,
  ytd-mini-guide-entry-renderer:hover {
    background-color: #6a2c9133 !important;
  }

  /* Item selecionado no menu */
  ytd-guide-entry-renderer[active] {
    background-color: #a6236e33 !important;
    border-left: 3px solid #ff4fa3 !important;
  }

  /* Fundo dos vídeos / cards */
  ytd-rich-grid-media, ytd-video-renderer, ytd-compact-video-renderer {
    background-color: #12141f !important;
  }

  /* Títulos dos vídeos */
  #video-title, .ytd-video-meta-block yt-formatted-string {
    color: #f0e6ff !important;
  }

  /* Textos secundários (canal, views, data) */
  #metadata-line, ytd-channel-name {
    color: #a68fd6 !important;
  }

  /* Botões (inscrever-se, curtir, etc) */
  ytd-subscribe-button-renderer button,
  #subscribe-button tp-yt-paper-button {
    background-color: #a6236e !important;
    color: #ffffff !important;
    border-radius: 20px;
  }

  /* Botão de like/dislike */
  ytd-menu-renderer #top-level-buttons-computed yt-icon {
    color: #ff4fa3 !important;
  }

  /* Barra de progresso do vídeo */
  .ytp-play-progress {
    background: linear-gradient(90deg, #6a2c91, #ff4fa3) !important;
  }

  /* Scrollbar */
  ::-webkit-scrollbar-thumb {
    background-color: #6a2c91 !important;
    border-radius: 10px;
  }
  ::-webkit-scrollbar-track {
    background-color: #0d1117 !important;
  }

  /* Caixa de comentários */
  ytd-comment-thread-renderer {
    background-color: #12141f !important;
  }

  /* Links */
  a {
    color: #ff4fa3 !important;
  }
}
